    setRawValues((prev) => ({ ...prev, [key]: raw }));
    const parsed = parseLocalizedNumber(raw);
    setFields((prev) => ({
      ...prev,
      [key]: parsed !== null ? coerceMonetary(parsed) : 0,
    }));
    // Minor: treat lone "-" or "." as incomplete, not invalid.
    const trimmed = raw.trim();
    const isPartialInput = trimmed === "-" || trimmed === ".";
    setParseErrors((prev) => {
      const hasError = trimmed !== "" && parsed === null && !isPartialInput;
      if (hasError && !prev.has(key)) {
        const next = new Set(prev);
        next.add(key);
        return next;
      }
      if (!hasError && prev.has(key)) {
        const next = new Set(prev);
        next.delete(key);
        return next;
      }
      return prev;
    });
  };
